\subsubsection*{0-form problem}
Let $\mathbf{u}_0 = u(\mathbf{x},t)$ and $\mathbf{u}_{0,t_0} = u_{t_0}(\mathbf{x})$ as in \eqref{eqn: grad_initial}. The spatial boundary condition \eqref{eqn: xbc} is computed as
\begin{equation*}
    \mathbf{n}_\mathbf{x}\wedge\mathbf{u}_0 = n_1u\,\dx + n_2u\,\dy + n_3u\,\dz + 0\cdot\dt = 0,
\end{equation*}
which implies $u=0$ on $\Gamma_\mathbf{x}$.  
The temporal boundary condition \eqref{eqn: tbc} reduces to
\begin{equation*}
    \mathbf{n}_{t_0}\wedge\mathbf{u}_0 = - u\,\dt = -u_{t_0}\,\dt = \mathbf{n}_{t_0}\wedge\mathbf{u}_{0,t_0},
\end{equation*}
which yields $u(\mathbf{x},t_0) = u_{t_0}(\mathbf{x})$ on $\Gamma_{t_0}$.  
From \Cref{tab: Hodge_star} and \Cref{remark: Hodge_star},
\begin{equation*}
    **_\alpha\mathrm{d}_0 \mathbf{u}_0 = (-\alpha\partial_xu)\,\dx +(- \alpha\partial_yu)\,\dy +(- \alpha\partial_zu)\,\dz +(- \varepsilon\partial_tu)\,\dt,
\end{equation*}
and applying $\iota_{\mathbf{n}_{T}}$ gives
\begin{equation*}
    \iota_{\mathbf{n}_{T}}(**_\alpha\mathrm{d}_0 \mathbf{u}_0) = -\varepsilon \partial_t u=0.
\end{equation*}
In summary, the boundary conditions \eqref{eqn: xbc}--\eqref{eqn: ebc} for the 0-form case are
\begin{equation*}
\left\{\begin{array}{rl}
   \text{$\mathbf{x}$-BC:}& u=0\quad \text{on } \Gamma_{\mathbf{x}}, \\[0.5ex]
     \text{$t_0$-BC:}& u(\mathbf{x},t_0) = u_{t_0}(\mathbf{x})\quad \text{on } \Gamma_{t_0},\\[0.5ex]
    \text{$\varepsilon$-BC:}& \varepsilon u_t(\mathbf{x},T) = 0 \quad \text{on } \Gamma_{T}.
\end{array}\right.
\end{equation*}
Thus, the spatial ($\mathbf{x}$-BC) and temporal ($t_0$-BC) boundary conditions are consistent with those of the $H(\textbf{grad})$ convection-diffusion problem \eqref{eqn: grad_boundary}--\eqref{eqn: grad_initial}, while the artificial boundary condition ($\varepsilon$-BC) 
corresponds to a terminal velocity induced by the artificial temporal perturbation \eqref{eqn: grad_neumann}, and which is trivially satisfied when $\varepsilon=0$.


\subsubsection*{1-form problem}
Let $\mathbf{u}_1 = u_1\,\dx + u_2\,\dy + u_3\,\dz$ with initial 1-form $\mathbf{u}_{1,t_0}=\mathbf{u}_{t_0}(\mathbf{x})\cdot\mathrm{d}\mathbf{x}$ prescribed in \eqref{eqn: curl_initial}.
The spatial boundary condition \eqref{eqn: xbc} is
\begin{align*}
    \mathbf{n}_\mathbf{x}\wedge\mathbf{u}_1 &= (n_2 u_3 - n_3u_2)\,\dy\wedge\dz +(n_3 u_1 - n_1u_3)\,\dz\wedge\dx\\ 
    &\quad\quad+(n_1 u_2 - n_2u_1)\,\dx\wedge\dy+0\cdot\dx\wedge\dt + 0\cdot\dy\wedge\dt + 0\cdot\dz\wedge\dt = 0,
\end{align*}
which corresponds to the tangential condition $\mathbf{n}\times \mathbf{u} = \mathbf{0}$ on $\Gamma_\mathbf{x}$.
The temporal boundary condition \eqref{eqn: tbc} is
\begin{equation*}
    \mathbf{n}_{t_0}\wedge\mathbf{u}_1 =  u_1\,\dx\wedge\dt + u_2\,\dy\wedge\dt + u_3\,\dz\wedge\dt = \mathbf{n}_{t_0}\wedge\mathbf{u}_{1,t_0},
\end{equation*}
so that $\mathbf{u}(\mathbf{x},t_0) = \mathbf{u}_{t_0}(\mathbf{x})$ on $\Gamma_{t_0}$.
For the artificial boundary condition \eqref{eqn: ebc}, 
\begin{align*}
    **_\alpha\mathrm{d}_1 \mathbf{u}_1 &= \alpha(\partial_yu_3 - \partial_zu_2)\,\dy\wedge\dz + \alpha(\partial_zu_1 - \partial_xu_3)\,\dz\wedge\dx\\
    &\quad\quad+\alpha(\partial_xu_2 - \partial_yu_1)\,\dx\wedge\dy + (-\varepsilon\partial_t u_1)\,\dx\wedge\dt\\
    &\quad\quad+(-\varepsilon\partial_t u_2)\,\dy\wedge\dt + (-
    \varepsilon\partial_t u_3)\,\dz\wedge\dt,
\end{align*}
and applying $\iota_{\mathbf{n}_{T}}$ yields
\begin{equation*}
    \iota_{\mathbf{n}_{T}}(**_\alpha\mathrm{d}_1 \mathbf{u}_1) = (-\varepsilon \partial_t u_1)\,\dx + (-\varepsilon \partial_t u_2)\,\dy + (-\varepsilon \partial_t u_3)\,\dz=0.
\end{equation*}
In summary, the boundary conditions \eqref{eqn: xbc}--\eqref{eqn: ebc} in the 1-form case are
\begin{equation*}
\left\{\begin{array}{rl}
   \text{$\mathbf{x}$-BC:}  &  \mathbf{n}\times\bu=\mathbf{0}\quad \text{on } \Gamma_{\mathbf{x}}, \\[0.5ex]
     \text{$t_0$-BC:}& \mathbf{u}(\mathbf{x},t_0) = \mathbf{u}_{t_0}(\mathbf{x})\quad \text{on } \Gamma_{t_0},\\[0.5ex]
     \text{$\varepsilon$-BC:}& \varepsilon \bu_t(\mathbf{x},T) = \mathbf{0} \quad \text{on } \Gamma_{T}.
\end{array}\right.
\end{equation*}
As in the $H(\textbf{grad})$ case, the spatial ($\mathbf{x}$-BC) and temporal ($t_0$-BC) conditions correspond to the given data in the $H(\textbf{curl})$ problem \eqref{eqn: curl_boundary}--\eqref{eqn: curl_initial}, while the artificial condition ($\varepsilon$-BC) gives a terminal velocity associated with the temporal perturbation.


\subsubsection*{2-form problem}
Let $\mathbf{u}_2 = u_1\,\dy\wedge\dz + u_2\,\dz\wedge\dx + u_3\,\dx\wedge\dy$ with initial 2-form 
$\mathbf{u}_{2,t_0}$ defined analogously.  The spatial boundary condition \eqref{eqn: xbc} becomes
\begin{align*}
    \mathbf{n}_\mathbf{x}\wedge\mathbf{u}_2 = (n_1u_1+n_2u_2+n_3u_3)\,\dx\wedge\dy\wedge\dz=0,
\end{align*}
which corresponds to the normal condition $\mathbf{u}\cdot \mathbf{n} = 0$ on $\Gamma_\mathbf{x}$.  
The temporal boundary condition \eqref{eqn: tbc} is
\begin{equation*}
    \mathbf{n}_{t_0}\wedge\mathbf{u}_2 =  (-u_1)\,\dy\wedge\dz\wedge\dt + (-u_2)\,\dz\wedge\dx\wedge\dt + (-u_3)\,\dx\wedge\dy\wedge\dt,
\end{equation*}
so that $\mathbf{u}(\mathbf{x},t_0) = \mathbf{u}_{t_0}(\mathbf{x})$ on $\Gamma_{t_0}$.  
For the artificial boundary condition \eqref{eqn: ebc},
\begin{align*}
    **_\alpha\mathrm{d}_2 \mathbf{u}_2 &= (-\alpha(\partial_xu_1+\partial_yu_2+\partial_zu_3))\,\dx\wedge\dy\wedge\dz \\
    &\quad\quad+(-\varepsilon\partial_tu_1)\,\dy\wedge\dz\wedge\dt +(-\varepsilon\partial_tu_2)\,\dz\wedge\dx\wedge\dt\\
    &\quad\quad+(-\varepsilon\partial_tu_3)\,\dx\wedge\dy\wedge\dt,
\end{align*}
and applying $\iota_{\mathbf{n}_{T}}$ yields
\begin{equation*}
    \iota_{\mathbf{n}_{T}}(**_\alpha\mathrm{d}_2 \mathbf{u}_2) = (-\varepsilon \partial_t u_1)\,\dy\wedge\dz + (-\varepsilon \partial_t u_2)\,\dz\wedge\dx + (-\varepsilon \partial_t u_3)\,\dx\wedge\dy=0.
\end{equation*}
In summary, the boundary conditions \eqref{eqn: xbc}--\eqref{eqn: ebc} for the 2-form case are
\begin{equation*}
\left\{\begin{array}{rl}
   \text{$\mathbf{x}$-BC:}& \bu\cdot\mathbf{n}=0\quad \text{on } \Gamma_{\mathbf{x}},       \\[0.5ex]
    \text{$t$-BC:}& \mathbf{u}(\mathbf{x},t_0) = \mathbf{u}_{t_0}(\mathbf{x})\quad \text{on } \Gamma_{t_0},\\[0.5ex]
     \text{$\varepsilon$-BC:}& \varepsilon \bu_t(\mathbf{x},T) = \mathbf{0} \quad \text{on } \Gamma_{T}.
\end{array}\right.
\end{equation*}
As in the previous cases, the spatial and temporal conditions match the $H(\textnormal{div})$ data \eqref{eqn: div_boundary}--\eqref{eqn: div_initial}, and the artificial condition specifies the terminal velocity.



\subsubsection*{3-form problem}
Let $\mathbf{u}_3 = u\,\dx\wedge\dy\wedge\dz$ with initial 3-form $\mathbf{u}_{3,t_0} = u_{t_0}\,\dx\wedge\dy\wedge\dz$ as in \eqref{eqn: temporal_initial}.
The spatial boundary condition \eqref{eqn: xbc} becomes
\begin{align*}
    \mathbf{n}_\mathbf{x}\wedge\mathbf{u}_3 = 0\cdot\dx\wedge\dy\wedge\dz\wedge\dt = 0,
\end{align*}
and yields no meaningful spatial boundary condition.
This occurs because the 3-form problem involves only the temporal derivative and thus does not need a spatial boundary condition.
The temporal boundary condition \eqref{eqn: tbc} is
\begin{equation*}
    \mathbf{n}_{t_0}\wedge\mathbf{u}_3 = (-u)\,\dx\wedge\dy\wedge\dz\wedge\dt=\mathbf{n}_{t_0}\wedge\mathbf{u}_{3,t_0},
\end{equation*}
so that $u(\mathbf{x},t_0) = u_{t_0}(\mathbf{x})$ on $\Gamma_{t_0}$.
For the artificial boundary condition \eqref{eqn: ebc}, 
\begin{align*}
    **_\alpha\mathrm{d}_3 \mathbf{u}_3 = (\varepsilon\partial_tu)\,\dx\wedge\dy\wedge\dz\wedge\dt,
\end{align*}
and applying $\iota_{\mathbf{n}_{T}}$ gives
\begin{equation*}
    \iota_{\mathbf{n}_{T}}(**_\alpha\mathrm{d}_3 \mathbf{u}_3) = (\varepsilon\partial_tu)\,\dy\wedge\dy\wedge\dz=0.
\end{equation*}
In summary, the boundary conditions \eqref{eqn: xbc}--\eqref{eqn: ebc} for the 3-form case are
\begin{equation*}
\left\{\begin{array}{rl}
    \text{$\mathbf{x}$-BC:}& \text{not applicable}      ,       \\[0.5ex]
    \text{$t$-BC:}& u(\mathbf{x},t_0) = u_{t_0}(\mathbf{x})\quad \text{on } \Gamma_{t_0},\\[0.5ex]
      \text{$\varepsilon$-BC:}& \varepsilon u_t(\mathbf{x},T) = 0 \quad \text{on } \Gamma_{T}.
\end{array}\right.
\end{equation*}
The temporal condition is consistent with the one in the $L^2$-temporal problem \eqref{eqn: temporal_initial}, and the artificial condition specifies the terminal velocity for the temporal perturbation, which vanishes as $\varepsilon$ goes to $0$.








\section{Variational formulation and well-posedness}\label{sec: well-posed}
In this section, we establish the well-posedness of the unified problem within a variational setting.  To this end, we first introduce an exponentially-fitted spatiotemporal flux operator tailored to the unified convection-diffusion framework, and then derive a variational formulation for the unified equation \eqref{eqn: physic_preserving_equation} together with the boundary conditions \eqref{eqn: xbc}--\eqref{eqn: ebc}.


\subsection{Exponentially-fitted spatiotemporal flux operator}\label{sec: exp_fitted_spatiotemporal}

Exponentially-fitted flux operators are designed to symmetrize fluxes in convection-diffusion problems.  
As a motivating example (see \cite{bank2017arbitrary,lazarov2012exponential} for more details), let $\psi(x,y,z,t)$ be a potential function satisfying $\nabla_\mathbf{y}\psi = D^{-1}\mathbf{b}$. Then, the $H(\textbf{grad})$ convection-diffusion flux $J(u)$ defined in \eqref{eqn: flux} can be expressed as
\begin{equation*}
    J(u) = D\nabla_\mathbf{y} u + \mathbf{b}u = D e^{-\psi}\nabla_\mathbf{y}(e^\psi u).
\end{equation*}
In stationary convection-diffusion problems, $H(\textbf{curl})$- and $H(\textnormal{div})$-type fluxes can also be expressed in similar exponential forms \cite{wu2020simplex}.
Such symmetrized flux operators enable the application of the well-established analytical framework for purely diffusive problems (e.g., the Poisson equation) to convection-diffusion problems. This facilitates proofs of well-posedness and provides a foundation for designing stabilized numerical methods for convection-dominated regimes (e.g.,~\cite{adler2023stable,wu2020simplex}).






Our objective here is to generalize this exponentially-fitted flux operator to the spatiotemporal setting and to use it to reformulate the unified equation \eqref{eqn: physic_preserving_equation}.
We assume there exists a spatiotemporal potential function $\psi_0 = \psi_0(x,y,z,t)$ as a 0-form satisfying
\begin{equation*}
    \dzero\psi_0 = \mathbf{b}_1,
\end{equation*}
where $\mathbf{b}_1$ is the spatiotemporal convection 1-form introduced in \eqref{eqn: spatiotemporal_convection}.  
\begin{remark}
    The assumption $\mathrm{d}_0\psi_0 = \mathbf{b}_1$ may not hold in full
generality.  Indeed, a potential $\psi_0$ can exist only when the convection
field $\bm{\beta}$ is curl-free, because the de~Rham complex requires
every exact 1-form to be closed ($\mathrm{d}_1\mathrm{d}_0\psi_0 = 0$).  
Moreover, since the spacetime convection 1-form 
$\mathbf{b}_1=\alpha^{-1}\boldsymbol\beta\cdot \mathrm{d}\mathbf x-\varepsilon^{-1}\mathrm{d}t$
contains both spatial and temporal components, closedness additionally
requires $\alpha$ and $\bm{\beta}$ to be time-independent so that no
mixed space-time terms (such as $\mathrm{d}x\wedge\mathrm{d}t$) appear in $\mathrm d_1\mathbf b_1$.
Many practical applications (including fluid and drift-diffusion
models) feature irrotational convection fields. From a numerical viewpoint, local (spatial and temporal) approximations of the
convection field used in discretizations naturally yield locally exact
1-forms. The exponentially-fitted flux operator therefore remains well-defined even
when the physical convection field varies in time.
For the sake of simplicity in this section, we
retain the assumptions that $\nabla\times\bm{\beta}=0$ and
$\partial\alpha/\partial t=\partial\bm{\beta}/\partial t=\mathbf{0}$, so that the potential $\psi_0$ is globally well-defined.
\end{remark}
With this definition, the spatiotemporal convection-diffusion flux operator is expressed in exponential form as follows.
\begin{lemma}\label{lemma: exp_fitted_flux}
    For any $k$-form $\bm{\omega}_k$ and potential function $\psi_0$, the spatiotemporal flux operator satisfies
\begin{equation}\label{eqn: exponential_fitted_flux}
    \mathrm{J}_k\bm{\omega}_k = e^{-\psi_0}{\rm{d}}_k(e^{\psi_0}\bm{\omega}_k).
\end{equation}
\end{lemma}

\begin{proof}
    We invoke the graded product rule for the exterior derivative:
\begin{equation*}
    \mathrm{d}_{m+k}(\bm{\eta}_m\wedge\bm{\omega}_k) = \mathrm{d}_m\bm{\eta}_m\wedge\bm{\omega}_k+(-1)^m\bm{\eta}_m\wedge\mathrm{d}_k\bm{\omega}_k,
\end{equation*}
valid for any $m$-form $\bm{\eta}_m$ and $k$-form $\bm{\omega}_k$.
Specializing to the case $m=0$ with $\bm{\eta}_0 = e^{\psi_0}$, 
\begin{align*}
    e^{-\psi_0}{\rm{d}}_k(e^{\psi_0}\bm{\omega}_k) &= e^{-\psi_0}\left( \dzero e^{\psi_0}\wedge \bm{\omega}_k + e^{\psi_0} \mathrm{d}_k\bm{\omega}_k\right)\\
    & = e^{-\psi_0}\left( e^{\psi_0}\mathbf{b}_1\wedge \bm{\omega}_k + e^{\psi_0} {\rm{d}}_k\bm{\omega}_k\right)\\
    & = \mathbf{b}_1\wedge\bm{\omega}_k + {\rm{d}}_k\bm{\omega}_k,
\end{align*}
where we used the chain rule $\dzero e^{\psi_0} = e^{\psi_0} \dzero\psi_0 = e^{\psi_0} \mathbf{b}_1$.
This establishes \eqref{eqn: exponential_fitted_flux}.
\end{proof}


Using the result of \Cref{lemma: exp_fitted_flux}, the unified spatiotemporal equation \eqref{eqn: physic_preserving_equation} becomes
\begin{equation*}
    \delta^{k}_{1\alpha}{\rm{J}}_k\mathbf{u}_k + {\rm{d}}_{k-1}\delta^{k-1}_{\alpha1}\mathbf{u}_k=\delta^{k}_{1\alpha} e^{-\psi_0}\mathrm{d}_ke^{\psi_0}\mathbf{u}_k + {\rm{d}}_{k-1}\delta^{k-1}_{\alpha1}\mathbf{u}_k=\mathbf{f}_k.
\end{equation*}
This equation shows that the unified spatiotemporal formulation modifies the Hodge-Laplacian structure through the exponential weight $e^{\psi_0}$: 
\[
    \delta_{1\alpha}^k \mathrm{d}_k\ (\text{in Hodge Laplacian})
    \quad \Rightarrow \quad
    (\delta_{1\alpha}^k e^{-\psi_0}) (\mathrm{d}_k e^{\psi_0}) \ (\text{in convection-diffusion}).
